# Project sheets ("fișa proiect") for the activity pages, from the association's Drive folder
# "6. Site AIS" (A1–A5, received 2026-10-16). The Romanian text is verbatim from the Word files;
# the English text next to it is the translation used on html/en/.
#
#   P(ro, en)        a paragraph
#   L([P, P, ...])   a bulleted list
#   LINK(ro, en, url) a "Label: url" line from the sheet, shown as a link
#
# Left out on purpose: the title line (already the page title), the "A1 | Erasmus+ Youth Exchange | …"
# line (shown as Perioada / Loc in the status board) and the EU disclaimer (already in the footer).

def P(ro, en):
    return ('p', ro, en)


def L(items):
    return ('ul', items)


def LINK(ro, en, url):
    return ('link', ro, en, url)


