def translations():
    """RO -> EN pairs for translate.py (decimal commas become points in English)."""
    import re
    dec = re.compile(r'(?<![\d,])(\d+),(\d{1,2})(?![\d,])')
    t = dict(UI)

    def add(ro, en):
        t[ro] = dec.sub(r'\1.\2', en)

    def walk(blocks):
        for b in blocks:
            if b[0] == 'p':
                add(b[1], b[2])
            elif b[0] == 'ul':
                walk(b[1])
            elif b[0] == 'link':
                add(b[1], b[2])
                t[b[3]] = b[3]
    t[OUTRO] = OUTRO
    for s in SHEETS.values():
        t[s['subtitle']] = s['subtitle']  # already English in the sheet
        t[s['project']] = s['project']
        add(*s['when'])
        add(*s['place'])
        add(*s['stamp'])
        walk(s['intro'])
        for (h_ro, h_en), blocks in s['sections']:
            add(h_ro, h_en)
            walk(blocks)
    for ro, en in STAMPS_EXTRA.values():
        add(ro, en)
    for ro, en in list(FACT_LABELS.values()) + list(LINK_LABELS.values()):
        add(ro, en)
    return t


def flaps():
    """Departure-board tiles: "NOI 2023" -> "NOV 2023"."""
    return {ro: en for ro, en in [s['stamp'] for s in SHEETS.values()] + list(STAMPS_EXTRA.values())}

